  nh_sea:{yy:[['yy',null,'安靜？我家很吵。有人會敲杯子，有人會問我今天吃什麼。'],['yy','smug','我選吵的。'],['cl','firm','姐姐，我的燈比牠們的亮。跟著我走。']],cl:[['cl','firm','這些燈，我一盞都不會留在這裡。'],['yy',null,'點燈的人回不去了。燈，我們帶回去。']],yx:[['yx',null,'留下來？這裡連個能罵的人都沒有，無聊死了。'],['yx',null,'讓開。上面有人欠我一句話。']]},
